import{_ as t}from"./chunks/768e0eb5f2579722fdd0.5vIVpAfU.js";import{_ as o,C as a,o as n,c as s,j as e,a as l,E as m,a6 as i}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"我是如何记住我学到的一切的","description":"","frontmatter":{"title":"我是如何记住我学到的一切的","originalTitle":"How I Remember Everything I Learn","date":"2022-11-12","originalUrl":"https://thedankoe.com/letters/how-i-remember-everything-i-learn/","minutes":13,"sourceHash":"91468f36f8f6db4764196cc1352312184fef1e3e351170f7747e6e0be90783be","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-i-remember-everything-i-learn/"}]]},"headers":[],"relativePath":"letters/how-i-remember-everything-i-learn.md","filePath":"letters/how-i-remember-everything-i-learn.md"}'),h={name:"letters/how-i-remember-everything-i-learn.md"};function c(g,p,f,b,u,d){const r=a("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"我是如何记住我学到的一切的",tabindex:"-1"},[l("我是如何记住我学到的一切的 "),e("a",{class:"header-anchor",href:"#我是如何记住我学到的一切的","aria-label":'Permalink to "我是如何记住我学到的一切的"'},"​")],-1)),m(r),p[1]||(p[1]=i('<p><a href="https://www.youtube.com/embed/2L0TjTIHEFo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>如果你和我一样，你会喜欢研究深奥的概念。</p><p>但是，这里有一种不协调感。</p><p>你觉得自己永远不可能像你最喜欢的作家、演说家，甚至是你在社交媒体上关注的人那样深刻、富有洞察力或具有影响力。</p><p>作为一个18岁时因为在大学停车库抽大麻而被捕的人，我试着去读了埃克哈特·托利（Eckhart Tolle）的《当下的力量》（The Power Of Now）。</p><p>我读得很仔细。</p><p>我练习了其中的冥想。</p><p>我敞开心扉，去接受上帝这一概念的可能性（作为一个叛逆的青少年，我曾经对此完全排斥）。</p><p>那本书改变了我的一切。它缓解了我对可能面临重罪指控的担忧。它帮助我冷静下来，对那些我不同意的人不再那么容易产生过激反应。</p><p>我并没有记住那本书里的所有内容，但我从中学到的东西，比在学校里<em>被要求</em>去读的任何其他书要多出十倍。</p><p>为什么我能记住那本书里那么多的内容？</p><p><strong>1) 确立意图</strong></p><p>我非常看重目标设定，无论你是否把它写下来。</p><p>当我读这本书的时候，它完美契合了我当时的生活处境。</p><p>我正处于人生的最低谷之一。我要么因为抽了“魔鬼的生菜”（大麻）而上法庭，并可能被判重罪，要么交出1万美元参加一个转处项目，然后每周被叫去随机往杯子里尿尿（尿检）。</p><p>作为一个即将进入大学二年级的19岁学生，这显然把我吓坏了。我没有钱，而且我TM绝不可能把这件事告诉我父母。</p><p>所以，当有人向我推荐《当下的力量》时，我抱有将它的教诲应用到我所处人生阶段的<em>意图</em>。</p><p>我愿意做任何事——并以极其开放的心态去阅读——让这些教诲彻底改变我的精神状态。</p><p><strong>2) 真正的好奇心</strong></p><p>我第一次听说这本书是从马特·奥格斯（Matt Ogus）那里。</p><p>对于那些不了解YouTube健身黄金时代的人来说，马特·奥格斯是最早的一批健身视频博主之一。</p><p>他是我渴望成为的那种人。他是我最早的数字导师之一（尽管他甚至都不知道）。</p><p>他在视频中多次推荐过这本书，而我产生了一种真正的好奇心，想去了解这整个关于“灵性”的事情到底是怎么回事。</p><p>通常情况下我是不会去读这本书的，但我信任马特，就像我确信你们中的一些人信任我一样。</p><p>好奇心迫使我读得很慢、很细致，并致力于理解书中到底在说什么——尤其是在那些难以理解的部分。</p><p><strong>3) 缩小执行差距</strong></p><blockquote><p>一个人能培养的最伟大的技能，就是缩短从想法到执行的时间。</p><p>— 丹·柯伊（DAN KOE） (@thedankoe) <a href="https://twitter.com/thedankoe/status/1522144576768823296?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 5, 2022</a></p></blockquote><p>那么，当我在读这本书时，如果遇到什么可以实践的东西，我会立刻放下书本。</p><p>我记得我端着咖啡坐在门廊外，试图调动我全部的五感，并进行了多次冥想练习。</p><p>因为这些想法在我脑海中还很新鲜，所以当冥想这种无形的东西起作用时，我更容易察觉到。</p><p>意识到它正在起作用，巩固了我脑海中的这个想法。</p><p>我有<em>直接经验</em>来支撑这个想法。</p><p>我把这些文字在现实中落了地。</p><p>确立意图、真正的好奇心，以及缩小执行差距，是能让你记住更多所学内容的绝佳方法——但我们可以做得更好。</p><p>多年来，我发现了一些方法，能让我选择去阅读、研究或学习的任何东西发挥出10倍的威力。以下就是我的发现。</p><h2 id="你在构建什么" tabindex="-1">你在构建什么？ <a class="header-anchor" href="#你在构建什么" aria-label="Permalink to &quot;你在构建什么？&quot;">​</a></h2><p><strong>实践（Praxis）</strong> （名词） — <em>与理论相对的行动或实践。</em></p><p>现代的问题在于信息过剩。</p><p>我们喜欢在缺乏直接经验的情况下，囤积理论、正统观念和对事物的概念性理解。因为那意味着我们必须去做一些我们觉得不舒服的事情，而我们早就习惯了呆在感知上的舒适区里。</p><p>生活不是这样运转的，也没人想成为Instagram评论区里的“那种人”。你懂的，就是那种给出了一整本书分量的举重（或商业）建议，但看起来却像是一辈子都没进过杠铃（或客户）10英尺范围内的人。</p><p>你会发现在大多数领域中，真正的专家极少需要指导。他们利用科学、理论和建议达到了中级阶段，但在进入高级阶段后，他们明白直觉和直接经验胜过一切。</p><p>除了发帖，我不再登录社交媒体了。我不想显得很傲慢，但99.99%的建议对我都不适用。它只会让我在精神、身体、财务和灵性上的训练中自我怀疑。我的实践，是有我经过经验淬炼的个人哲学在背后支撑的。</p><p>那么，我们如何平衡实践与理论呢？</p><p><em><strong>通过成为一个构建者。</strong></em></p><p>也就是说，始终要有一个与你正在学习的理论相契合的构建项目。</p><p>当我在学Photoshop时，我一开始就是没完没了地看关于如何使用这款软件的教程。这只会导致我陷入“教程地狱”中无法自拔。</p><p>而当真正要创作点什么的时候，我却一无所知。</p><p>我不得不寻找特定的教程，来辅助我正在构建的东西。</p><p>一旦我意识到这种学习方式——有一个可以应用我知识的项目——能让我记住多少东西，我就完全转向了这种方法。</p><p>如果我想学习如何建网站，我不会先开始学习。我会挑选一个用来建站的软件，然后看一个关于如何建立该网站的长教程。</p><p>我不会完全照着教程做，因为我不想做出一模一样的东西。我运用我学到的东西，<em>艰难地</em>尝试去创建我自己的网站。这种挣扎让我的大脑做好了准备，将所学的课程“锁定”在脑海里。</p><p>那么，为什么这种方法对保留信息有效呢？</p><p><strong>1) 强制同步性</strong></p><p>新奇感、模式识别以及参与这两者的多巴胺，对学习来说至关重要。</p><p>当我们的祖先注意到新事物时，他们会记住它，特别是当它与他们的生存息息相关时。</p><p>比如，如果他们路过一丛光秃秃的灌木，而这灌木他们已经见过很多次了，这就意味着它毫无新意，对他们的生存也没有帮助。但当灌木上长出新的浆果时，他们注意到了这个新变化，并<em>记住</em>了它长了浆果，因为这在他们生命中的某个时刻可能会有帮助。</p><p>当你从一个要构建的项目开始时，你的思维就会拓宽，去注意到那些有助于该项目存活下来的事物。</p><p>就像《当下的力量》与我当时的生活处境息息相关一样。书中的教诲印刻在了我的意识中。那种新奇发现所带来的多巴胺，给了我立刻去实践的兴奋感。</p><p>如果你不专注，你就<em>看不见</em>。</p><p>有一个项目来集中你的注意力，能让你看到你平时看不到的东西。</p><p>这不<em>仅仅</em>是一个学习技巧，更是一个提升生活质量的技巧，我们将在下一节中把它放大10倍。</p><p><strong>2) 灵感行动法则</strong></p><blockquote><p>我只在灵感来袭时写作。幸运的是，它每天早上九点都会准时来袭。——威廉·福克纳（William Faulkner）</p></blockquote><p>每个人都知道，在灵感的驱使下，他们能表现得更好。</p><p>人们喜欢在去健身房练胸之前，看一些“最佳练胸动作”的视频。</p><p>我喜欢在坐下来写作之前，读一读那些能启发我的作家的作品。</p><p>有了项目，你就会被驱使着去进行相匹配的学习。</p><p>如果你在建立一家企业，你自然会倾向于去获取那些能为你建立企业带来灵感的信息。</p><p><em>但你必须得开始去建立那个该死的企业。</em></p><p><strong>3) 特定知识</strong></p><p>如果你订阅这封时事通讯有一段时间了，你就会知道我是这条建议的拥趸：</p><p><em>先开始，后学习。</em></p><p>当你开始时，<em>即使你不知道自己在干什么</em>，你也会遇到问题。</p><p>这些问题会引发挣扎，并让你的大脑做好学习的准备。</p><p>这些问题也会给你提供特定的研究对象。</p><p>你不会盲目地、毫无背景地学习，也不会从一个并没有教你<em>确切</em>想要做什么的人那里学习。当你盲目学习时，你会摄入太多的“信息脂肪”。就像你想增肌时采用脏增肌（dirty bulk）而不是干净增肌（lean bulk）一样……最终你会感到迟钝、疲惫、昏昏沉沉，直到你不得不去减脂。</p><p>不要提问。不要盲目学习。开始构建一些东西，然后为了解决弹出的特定问题去提问或研究。</p><p>然后把这个过程重复十年。</p><h2 id="你就是那个项目-——-将这一切联系起来" tabindex="-1">你就是那个项目 —— 将这一切联系起来 <a class="header-anchor" href="#你就是那个项目-——-将这一切联系起来" aria-label="Permalink to &quot;你就是那个项目 —— 将这一切联系起来&quot;">​</a></h2><blockquote><p>如果你想学得更快，不要直接开始学习。\\</p><p>– 规划一个项目<br> – 开始将其构建出来<br> – 在这个过程中学习\\</p><p>太多人陷入了教程地狱，堆砌无用的知识，最终让大脑一片混沌。\\</p><p>开始 &gt; 遇到问题 &gt; 寻找特定知识来解决它。</p><p>— 丹·柯伊（DAN KOE） (@thedankoe) <a href="https://twitter.com/thedankoe/status/1591086400685891588?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 11, 2022</a></p></blockquote><p>让我们更进一层。</p><p>构建能帮助你记住更多知识。</p><p>但是教学能让你记住更多。教学是另一种模式，它能锁定你从构建中获得的经验。</p><p>所以，为什么不把这两者结合起来，从而创造一种充满机缘巧合、同步性以及优质多巴胺的生活呢？</p><p>我们通过把<em>你</em>变成这个项目来实现这一点。</p><p>这意味着全面的发展。</p><p>个人发展不仅来自于提升你自己，还来自于你对世界产生的影响。</p><p>换句话说，你的事业。</p><p>或者对于那些对“事业”一词有所“共鸣”的人来说，把它替换为你一生的工作、你的使命，或者你打算如何让这个世界比你离开时更美好。</p><p>自私与无私的极性。</p><p>提升你自己，然后帮助他人提升。把电梯送回去。攀登高山，并在你身后留下别人可以跟随的踪迹。</p><p><em>记录你的旅程，让别人能进化得更快。</em></p><p><em>尽你的一份力去提升集体意识。</em></p><p><em>这就是“事业”的本质，然而许多人却把它误认为某种吸干你……嗯，吸干你生活心血的超大企业。</em></p><p>我已经做到了这一点（并且帮助了成千上万的人），将他们自己变成一家企业，这样他们就可以研究自己的兴趣，传授他们的发现，并凭借他们作为构建者和教师的天性来获得创造性的收入。</p><p>那么，让我们把学到的一切归结为6个步骤：</p><p><strong>1) 确立意图</strong></p><p>设定一个目标。创建一个目的。思考你的“为什么”。随便你怎么去定义它。</p><p>确立一个意图去改善你的生活，去实现你的潜力。</p><p>这会把你的注意力集中在未来，同时鼓励你将能量引向那个愿景。你所引导的能量来自于你的日常行动。</p><p>你所吸收的一切都将开始为你的愿景提供燃料。</p><p><strong>2) 安排创意时间块</strong></p><p>所有人都知道应该为深度工作安排时间，但是什么在为这种深度工作提供燃料呢？</p><p>如果你是一个创作者，你会在空闲时间里寻找灵感吗？还是你是在油箱空空的情况下强行“创作”？</p><p>你是重视创造力的自发本性，还是沦为了刻板工作和效率应用程序的奴隶？</p><p>我并不是在让你摒弃日常习惯、效率和生产力。我是在告诉你，它们只是拼图的一部分。</p><p>每天安排30分钟的散步。</p><p>在散步时，你可以：</p><ul><li>听一听与你的意图相关的有声书或播客</li><li>思考你的未来，让你的大脑去解决问题</li><li>远离那些会让你处于非创造状态的干扰</li></ul><p>当你把注意力从外部转向内部时，默认模式网络（Default Mode Network，一个心理学名词）就会开始发挥作用。这时，你的大脑开始咀嚼你吸收的信息，为你的意识带来新的发现。（这与生活在<a href="https://thedankoe.com/the-cure-to-caring-what-people-think/" target="_blank" rel="noreferrer">压力导致的狭隘关注</a>状态截然相反）。</p><p><strong>3) 建立一个笔记系统</strong></p><p>关于如何正确做笔记，我完全可以写一整本书，所以我不打算在这里赘述，你只需下载我免费的笔记系统（以及包含如何最高效使用它的7天挑战）即可。</p><p>你会在笔记里写些什么呢？</p><p>任何能为你构建的事业提供<em>燃料</em>的信息、洞察或发现。</p><p>当你的大脑锁定了一个未来的目标时，你的认知视野就会扩大。不管你是否有所察觉，你都开始从噪音中过滤出信号。</p><p>就像你第一次发现某款车一样。你以前从未密切关注过它，但你很喜欢它的外观。然后，就像变魔术一样，你开始到处都能注意到这款车。</p><p>我的朋友兼编辑德万（Devan）自从吉普角斗士（Jeep Gladiator）上市以来就一直很讨厌它，结果他现在就像中了邪一样，每天都能看到它们三四次。</p><p>想象一下，如果你热爱提升自己大脑、身体和财务状况的想法——你就会开始每天都能发现各种机会（那些通常会在你眼皮子底下溜走的机会）。</p><p><strong>4) 构建你生活的方方面面</strong></p><blockquote><p>你之所以看不到进展，是因为你痴迷于完美的结果，而不是创造结果的过程。</p><p>— 丹·柯（DAN KOE） (@thedankoe) <a href="https://twitter.com/thedankoe/status/1591070525585084417?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年11月11日</a></p></blockquote><p>你必须明白，你是在<em>构建</em>。</p><p>独自建一栋豪宅需要多长时间？</p><p>20年？还是一辈子？</p><p>这正是关键所在。</p><p>爱上无限游戏吧。</p><p>尝试一切让你感兴趣的事物。然后加倍投入到那个你可以预见自己余生都在做的事情上。是的，这需要时间，需要试错，还需要6到12个月的耐心。</p><p>如果你不喜欢听这些，那就坐下来想想其他的选择是什么。我敢打赌，你会更不喜欢听那个。</p><p>让自己从即时满足的心态中清醒过来。你必须每天主动去构建你的生活。</p><p>从30到60分钟开始。</p><p>在这段时间里你要做什么？</p><p>去健身。为了数字杠杆和收入去写作。当你在构建过程中对遇到的问题感到迷茫时，进行自我教育。</p><p><em>如果你不抽出时间为自己构建，你</em> <em>就会被分配</em> <em>时间去为别人构建。</em></p><p><strong>5) 教授你所知道的</strong></p><p><img src="'+t+'" alt=""></p><p>正如我们所讨论的，构建是一种保留特定知识的绝佳方式，这些知识与你试图构建的生活相一致。</p><p>为了保留更多你所学到的东西，让我向你介绍一下<em>门徒效应</em>（Protégé Effect）。</p><p>简而言之，就是“以教促学”。</p><p>当你把真正的好奇心与构建一个项目结合起来，然后把你学到的东西教给别人，你就能比用其他任何方法更好地提升你的表达能力。</p><p>显然，我最喜欢的将这一切结合起来的方法，就是踏入数字竞技场。</p><p>雇主正在根据你的公开简历（社交媒体账号）进行招聘。你可以通过受众的形式，把你学到的东西教给别人，以此来建立数字杠杆。而当你准备好了，你就可以创造一款产品或服务，把你的兴趣转化为收入。</p><p>当你教授有关你热爱的事物时，你会在日常生活中解锁一种全新水平的机缘巧合（serendipity）。</p><p><strong>6) 将它变成你一生的事业</strong></p><blockquote><p>你生活中将会出现的机缘巧合的数量，即你的幸运表面积，与你做自己热爱之事的程度，以及有效传达给的总人数成正比。 —— 杰森·罗伯茨（Jason Roberts）</p></blockquote><p>工作是生活不可或缺的一部分，对大多数人来说，它消耗了他们清醒时间中的很大一部分比例。</p><p>对许多人来说，这种工作缺乏乐趣。他们走上了别人为他们铺就的传统道路，生活在一种压力微微升高的状态中（这对你的创造性问题解决能力来说非常糟糕）。</p><p>这是你想要的吗？</p><p>如果要维持工作与休息的二元对立——这意味着“退休”是一个梦，在这个梦里你依然会做<em>些什么</em>——你难道想让自己70%的人生被消耗在做你讨厌，或者哪怕只是有点不喜欢的事情上吗？</p><p>不想吗？换作是我，我会这么做。</p><ul><li>研究那些你感到被吸引去研究的东西。</li><li>不要分心。让它把你拉进探索的兔子洞深处。</li><li>要明白：<em><strong>持续的好奇心 + 兴奋感 = 激情</strong></em></li><li>用我们在这里讨论过的一切方法，练习去维持那种激情。</li><li>记下你的发现，构建一个项目，并开始教导他人。</li></ul><p>我已经多次谈论过<a href="https://youtu.be/BZ2nSULolKI" target="_blank" rel="noreferrer">通过一人企业将自己产品化</a>，以及<a href="https://youtu.be/RuFjY1MV4LM" target="_blank" rel="noreferrer">成为一名价值创作者</a>。</p><p>许多人没有意识到的是，<em>产品都是从项目开始的</em>。</p><p>如果你自己就是那个<em>项目</em>，当你把自己展现在公众面前时，你就会变成一个人们想要投资的<em>产品</em>。</p><p>先将自己项目化，然后将自己产品化。</p><p>现在，你要明白，你不能等产品完美了才发布，那是一个不可能实现的目标。</p><p>企业家发布的是 MVP（Minimum Viable Products），即最小可行产品。一个能提供足够价值以供收费、发布并随着时间推移不断改进的项目。</p><p><em>你本身，就是你一生的事业。</em></p><p>你的最小可行产品在你出生时就被创造出来了。</p><p>发布，构建，传授。</p><p>—— 丹·柯</p><p><strong>本周动态</strong></p><p>首先，如果你想把我们在这封信中讨论的一切都付诸实践——数字经济学（Digital Economics）课程将开放报名至11月23日。此次仅限大师（Masters）课程。</p><p><a href="https://upgrade.digitaleconomics.school/" target="_blank" rel="noreferrer">如果你想确保自己未来成为一名价值创作者，请在这里加入。</a></p><p>上周，我发布了一个 YouTube 视频，讲的是我创办一人企业时希望自己能早点知道的11件事。明天，我将发布《独处的力量》（The Power Of Being Alone），这将帮助你成为真实的自己。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">在这里观看这两个视频。</a></p><p>在 Modern Mastery 中，我们进行了不可思议的讨论，探讨了如何在建立受众的同时从一开始就实现变现（而不是等到某个虚构的粉丝数才开始获取收入）。在过去一周里，我们的成员增加了250多名。Discord 频道比以往任何时候都要活跃。本周我将发布一项关于‘广泛特殊性的艺术’（The Art Of Broad Specificity）的培训。换言之，就是如何让你细分领域的兴趣对广大受众产生吸引力（从而真正获得互动并通过内容实现增长）。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需支付5美元即可加入。</a></p><hr><p><a href="/en/letters/how-i-remember-everything-i-learn">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',168))])}const y=o(h,[["render",c]]);export{w as __pageData,y as default};
